__doc__ = """Resizable generic buffer abstraction used by backend helper code."""


class Buffer:
    """A managed buffer, reallocates automatically it if necessary"""

    DTYPE_MAP = {}

    def __init__(self, dtype, growth=1.37, min_size=1, max_size=None):
        # store the size. Has value None until initialized
        self._size = None

        # store the data type. Cannot be changed
        self._dtype = type(self).map_dtype(dtype)

        # store the acutal buffer reference. Has value None until initialized
        self._buffer = None

        # add some extra growth to avoid too much reinitialization
        self._gfac = growth

        # handle checks for max and min size parameters
        if max_size is not None:
            if not isinstance(max_size, int):
                raise TypeError(
                    "max_size parameter must be of type int or None"
                )
        if not isinstance(min_size, int):
            raise TypeError("min_size parameter must be of type int")

        # introduce max and min size to avoid faulty initialization (e.g. size 0)
        # and memory limits
        self._max_size = max_size
        self._min_size = min_size

    @classmethod
    def map_dtype(cls, dtype):
        """map the dtype to a supported one"""
        if dtype not in cls.DTYPE_MAP:
            if dtype in cls.DTYPE_MAP.values():
                return dtype
            raise TypeError(f"data type {dtype} unsupported")
        return cls.DTYPE_MAP[dtype]

    def create_new_buffer(self, size, dtype):
        """create the actual buffer object"""
        raise NotImplementedError("Must be implemented in subclass")

    @property
    def dtype(self):
        """access the data type, read-only access"""
        return self._dtype

    @property
    def buffer(self):
        """access the buffer reference as pseudo-read-only, include some safety checks"""
        if self._buffer is None:
            raise ValueError("Buffer not initialized")
        return self._buffer

    @property
    def size(self):
        """request the actual size of the buffer, read-only and safety checks"""
        if self._size is None:
            raise ValueError("Buffer not initialized")
        return self._size

    def request(self, size, allow_grow=True):
        """request a buffer with a certain size"""
        if not isinstance(size, int):
            raise TypeError("size parameter must be of type int")
        if self._max_size is not None:
            if size > self._max_size:
                raise ValueError("Requested buffer exceeds maximum size")
        if self._size is None or size > self._size:
            if allow_grow:
                new_size = 1 + int(size * self._gfac)
                if self._max_size is not None:
                    new_size = min(self._max_size, new_size)
            self.set_size(new_size)
        return self.buffer[:size]

    def set_size(self, size):
        """set the size exactly as long as between max and min limits"""
        if self._max_size is not None:
            if size > self._max_size:
                raise ValueError("Requested buffer exceeds maximum size")
        if size < self._min_size:
            raise ValueError("Requested buffer below minimum size")
        self.reinitialize_buffer(size)
        return self.buffer

    def reinitialize_buffer(self, size):
        """reinitialize the buffer with a new size"""
        if not isinstance(size, int):
            raise TypeError("size parameter must be of type int")
        size = max(size, self._min_size)
        self._buffer = self.create_new_buffer(size, self.dtype)
        self._size = size
        return self.buffer

    def __call__(self, size=None):
        if size is not None:
            return self.request(size)
        return self.buffer
